import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireAssert Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireAssert/aireassert-v1-3-6.md","filePath":"aireblock-releases/AireAssert/aireassert-v1-3-6.md","lastUpdated":1789399292000}`),a={name:`aireblock-releases/AireAssert/aireassert-v1-3-6.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireassert-release-notes" tabindex="-1"><span class="fsc-product"><img src="/aireassert-icon.png"> AireAssert Release Notes</span> <a class="header-anchor" href="#aireassert-release-notes" aria-label="Permalink to “AireAssert Release Notes”">​</a></h1><blockquote><p><strong>Version:</strong> v1.3.6<br><strong>Release Date:</strong> 23 September 2026</p></blockquote><h4 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h4><ul><li>Inline Warnings for Unknown Form Controls (AA-677)</li><li>Image Upload Control Support (AA-720)</li><li>Configurable Subject Alias (AA-886)</li><li>Added security.txt for Responsible Disclosure (AA-1000)</li><li>Improved Unsaved Changes Warnings (AA-1014)</li><li>Notification for Unsynced Repository Changes (AA-1023)</li><li>Log Levels for Test Results (AA-1028)</li><li>Faster, More Efficient Saving (AA-1041)</li></ul><h4 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h4><ul><li>Fixed Incorrect Form Submission Status (AA-995)</li></ul><h4 id="🔧-tasks" tabindex="-1">🔧 Tasks <a class="header-anchor" href="#🔧-tasks" aria-label="Permalink to “🔧 Tasks”">​</a></h4><ul><li>Cleaner AireForms Logs in Test Results (AA-1034)</li><li>Cleaner AireFrame Logs in Test Results (AA-1035)</li><li>Removed Noisy Action/Page Log Entries (AA-1036)</li><li>More Readable Log Ordering (AA-1037)</li><li>Clearer Error Messages in Logs (AA-1038)</li><li>Improved Log Formatting (AA-1039)</li><li>Removed Redundant Test Start/Finish Log Entries (AA-1040)</li><li>Real-Time Filename Updates (AA-1047)</li></ul><h1 id="detailed-changes" tabindex="-1">Detailed Changes <a class="header-anchor" href="#detailed-changes" aria-label="Permalink to “Detailed Changes”">​</a></h1><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><hr><h4 id="inline-warnings-for-unknown-form-controls-aa-677" tabindex="-1">Inline Warnings for Unknown Form Controls (AA-677) <a class="header-anchor" href="#inline-warnings-for-unknown-form-controls-aa-677" aria-label="Permalink to “Inline Warnings for Unknown Form Controls (AA-677)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The test editor now underlines form control references (labels or IDs) that don&#39;t exist in the form&#39;s test map, in addition to the existing syntax-error squiggles.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>When writing or editing a test, you&#39;ll immediately see a warning underline if you reference a form control that doesn&#39;t actually exist on the form, helping you catch mistakes before running the test.</p></div><h4 id="image-upload-control-support-aa-720" tabindex="-1">Image Upload Control Support (AA-720) <a class="header-anchor" href="#image-upload-control-support-aa-720" aria-label="Permalink to “Image Upload Control Support (AA-720)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Test steps can now interact with image upload controls on forms.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can now write and run tests that cover forms with image upload fields.</p></div><h4 id="configurable-subject-alias-aa-886" tabindex="-1">Configurable Subject Alias (AA-886) <a class="header-anchor" href="#configurable-subject-alias-aa-886" aria-label="Permalink to “Configurable Subject Alias (AA-886)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>AireAssert can now read a tenant&#39;s configured Subject alias (for example &quot;Patient&quot; or &quot;Student&quot;) from AireFrame, and commands that reference &quot;Subject&quot; will accept the configured alias instead, including its plural form.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>If your organisation refers to subjects by another name, you can write your tests using that same terminology instead of always saying &quot;Subject&quot;.</p></div><h4 id="added-security-txt-for-responsible-disclosure-aa-1000" tabindex="-1">Added security.txt for Responsible Disclosure (AA-1000) <a class="header-anchor" href="#added-security-txt-for-responsible-disclosure-aa-1000" aria-label="Permalink to “Added security.txt for Responsible Disclosure (AA-1000)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>A security.txt file has been added, following the industry-standard format, giving security researchers a clear, standard channel for reporting vulnerabilities.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>There&#39;s now a clear, recognised way for security researchers to report any vulnerabilities they find, helping issues get reported and fixed responsibly.</p></div><h4 id="improved-unsaved-changes-warnings-aa-1014" tabindex="-1">Improved Unsaved Changes Warnings (AA-1014) <a class="header-anchor" href="#improved-unsaved-changes-warnings-aa-1014" aria-label="Permalink to “Improved Unsaved Changes Warnings (AA-1014)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The unsaved changes dialog now offers a &quot;save and continue&quot; option, and it&#39;s clearer which files and folders have unsaved changes. This also addresses cases where navigating to and from the manage repositories screen could otherwise leave a test running against an old, unsaved version.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>If you have unsaved changes, you can save and continue in one step, and you can see exactly which files or folders still have unsaved edits.</p></div><h4 id="notification-for-unsynced-repository-changes-aa-1023" tabindex="-1">Notification for Unsynced Repository Changes (AA-1023) <a class="header-anchor" href="#notification-for-unsynced-repository-changes-aa-1023" aria-label="Permalink to “Notification for Unsynced Repository Changes (AA-1023)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>AireAssert now notifies you when your repository has unsynced upstream changes, prompting you to sync.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You&#39;ll be alerted when there are upstream changes you haven&#39;t pulled yet, so you&#39;re less likely to work from an out-of-date test repository.</p></div><h4 id="log-levels-for-test-results-aa-1028" tabindex="-1">Log Levels for Test Results (AA-1028) <a class="header-anchor" href="#log-levels-for-test-results-aa-1028" aria-label="Permalink to “Log Levels for Test Results (AA-1028)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Log entries now carry a level (debug, info, warning or error). Debug-level entries are hidden from the main User Logs by default, though still available under UI Test Logs, and each remaining line shows its level at the start, for example &quot;Info: ...&quot;.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>The main results screen shows only the log detail that matters to you, with warnings and errors clearly labelled so you don&#39;t have to hunt for them.</p></div><h4 id="faster-more-efficient-saving-aa-1041" tabindex="-1">Faster, More Efficient Saving (AA-1041) <a class="header-anchor" href="#faster-more-efficient-saving-aa-1041" aria-label="Permalink to “Faster, More Efficient Saving (AA-1041)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Saving in the UI previously sent the entire test set to the test run manager and re-synced everything with git on every save. Saving now only sends changed data and communicates with git more efficiently.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>Saving your changes should feel noticeably faster, especially on larger test sets.</p></div><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><hr><h4 id="fixed-incorrect-form-submission-status-aa-995" tabindex="-1">Fixed Incorrect Form Submission Status (AA-995) <a class="header-anchor" href="#fixed-incorrect-form-submission-status-aa-995" aria-label="Permalink to “Fixed Incorrect Form Submission Status (AA-995)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>A form submission was completing successfully, but AireAssert was reporting it as unsuccessful. This has been fixed so successful submissions are correctly recognised.</p></div><h3 id="🔧-tasks-1" tabindex="-1">🔧 Tasks <a class="header-anchor" href="#🔧-tasks-1" aria-label="Permalink to “🔧 Tasks”">​</a></h3><hr><h4 id="cleaner-aireforms-logs-in-test-results-aa-1034" tabindex="-1">Cleaner AireForms Logs in Test Results (AA-1034) <a class="header-anchor" href="#cleaner-aireforms-logs-in-test-results-aa-1034" aria-label="Permalink to “Cleaner AireForms Logs in Test Results (AA-1034)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Unnecessary AireForms log entries have been removed from the Test Results screen.</p></div><h4 id="cleaner-aireframe-logs-in-test-results-aa-1035" tabindex="-1">Cleaner AireFrame Logs in Test Results (AA-1035) <a class="header-anchor" href="#cleaner-aireframe-logs-in-test-results-aa-1035" aria-label="Permalink to “Cleaner AireFrame Logs in Test Results (AA-1035)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Unnecessary AireFrame log entries have been removed from the Test Results screen.</p></div><h4 id="removed-noisy-action-page-log-entries-aa-1036" tabindex="-1">Removed Noisy Action/Page Log Entries (AA-1036) <a class="header-anchor" href="#removed-noisy-action-page-log-entries-aa-1036" aria-label="Permalink to “Removed Noisy Action/Page Log Entries (AA-1036)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Internal &quot;### action&quot; and &quot;### page&quot; log entries have been removed from the Test Results screen.</p></div><h4 id="more-readable-log-ordering-aa-1037" tabindex="-1">More Readable Log Ordering (AA-1037) <a class="header-anchor" href="#more-readable-log-ordering-aa-1037" aria-label="Permalink to “More Readable Log Ordering (AA-1037)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Logs have been reordered to read more naturally, for example simplifying an entry like &quot;### Action: First Name: Setting value to...&quot; down to &quot;First Name: ...&quot;.</p></div><h4 id="clearer-error-messages-in-logs-aa-1038" tabindex="-1">Clearer Error Messages in Logs (AA-1038) <a class="header-anchor" href="#clearer-error-messages-in-logs-aa-1038" aria-label="Permalink to “Clearer Error Messages in Logs (AA-1038)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Error logs previously included a raw error payload and full stack trace. These have been replaced with a concise, plain-language error message.</p></div><h4 id="improved-log-formatting-aa-1039" tabindex="-1">Improved Log Formatting (AA-1039) <a class="header-anchor" href="#improved-log-formatting-aa-1039" aria-label="Permalink to “Improved Log Formatting (AA-1039)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Log output, including embedded JSON, is now better formatted and easier to read, with improved presentation such as colouring and text wrapping.</p></div><h4 id="removed-redundant-test-start-finish-log-entries-aa-1040" tabindex="-1">Removed Redundant Test Start/Finish Log Entries (AA-1040) <a class="header-anchor" href="#removed-redundant-test-start-finish-log-entries-aa-1040" aria-label="Permalink to “Removed Redundant Test Start/Finish Log Entries (AA-1040)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The &quot;test started&quot; and &quot;test finished&quot; log entries have been removed from the Test Results screen.</p></div><h4 id="real-time-filename-updates-aa-1047" tabindex="-1">Real-Time Filename Updates (AA-1047) <a class="header-anchor" href="#real-time-filename-updates-aa-1047" aria-label="Permalink to “Real-Time Filename Updates (AA-1047)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Renaming a test file now updates the filename shown at the top of the file immediately, rather than only updating the name in the file list.</p></div>`,57)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};